// case output bird:output IGNORED

// YANG Actions


enum yang_proc_state
uytc_rpc(struct yang_session *se)
{
  if (!se->rpc)
  {
    se->rpc = mb_alloc(yang_pool, sizeof(*se->rpc));
    se->rpc->state = RPC_BEFORE;
  }

  const char *payload = se->coap.parser.payload;
  uint len = se->coap.parser.payload_chunk_len;
  if (se->coap.parser.state == COAP_PS_PAYLOAD_COMPLETE &&
    se->coap.parser.payload_total_len == 0)
  {
    struct coap_tx_option *cf = COAP_TX_OPTION_INT(COAP_OPT_CONTENT_FORMAT, (u16) COAP_CF_YANG_INSTANCES);
    coap_tx_send(&se->coap, COAP_TX_RESPONSE(&se->coap, COAP_RESP_CHANGED, cf));
    se->rpc->state = RPC_DONE2; // goto rpc_cleanup;
  }

  int running = 1;
  while (running)
  {
    enum yang_proc_state yp;
    switch (se->rpc->state)
    {
    case RPC_BEFORE:
      switch (cbor_parse_byte(se->cbor, payload[0]))
      {
      case CPR_MAJOR:
	if (se->cbor->type == CBOR_MAP)
	  se->rpc->state = RPC_MAP_OPENED;
	else
	{
	  log(L_INFO "uytc_rpc error: expected RPC map, got invalid major type");
	  se->rpc->state = RPC_ERROR; // goto rpc_error;
	}
	break;
      case CPR_MORE:
	return YP_WAIT;
      default:
	log(L_INFO "uytc_rpc error: expected RPC map, got something else");
	se->rpc->state = RPC_ERROR;  // goto rpc_error;
      }

      len--;
      payload++;
      if (!len)
	return YP_WAIT;

      /* fall through */
    case RPC_MAP_OPENED:
      switch (cbor_parse_byte(se->cbor, payload[0]))
      {
      case CPR_MAJOR:
	se->rpc->state = RPC_KEY;
	break;
      case CPR_MORE:
	return YP_WAIT;
      default:
	log(L_INFO "uytc_rpc: rpc id decode unexpected state");
	se->rpc->state = RPC_ERROR;  // goto rpc_error;
      }

      switch (se->cbor->type)
      {
      case CBOR_POSINT:
	se->rpc->rpc_sid = se->cbor->value;
	se->rpc->state = RPC_KEY;
	break;
      case CBOR_NEGINT:
	log(L_INFO "uytc_rpc: rpc id invalid major type (negative int as absolute SID)");
	se->rpc->state = RPC_ERROR;  // goto rpc_error;
	continue;
      case CBOR_TAG:
	log(L_INFO "uytc_rpc: tagged SID/array/string not supported");
	se->rpc->state = RPC_ERROR; // goto rpc_error;
	continue;
      case CBOR_ARRAY:
	log(L_INFO "uytc_rpc: identifier with SID in array not supported");
	se->rpc->state = RPC_ERROR; // goto rpc_error;
	continue;
      case CBOR_TEXT:
	log(L_INFO "uytc_rpc: rpc identifier must be SID, not string name");
	se->rpc->state = RPC_ERROR; // goto rpc_error;
	continue;
      default:
	se->rpc->state = RPC_ERROR; // goto rpc_error;
	continue;
      }

      /* fall through */
    case RPC_KEY:
      switch (se->rpc->rpc_sid)
      {

      case 60001: // SID bird:cli-show-memory
	yp = fn_bird_cli_show_memory(se);
	break;

      case 60025: // SID bird:cli-load-config
	yp = fn_bird_cli_load_config(se);
	break;

      case 60030: // SID bird:cli-show-status
	yp = fn_bird_cli_show_status(se);
	break;
      default:
	log(L_INFO "uytc_rpc: unknown rpc sid %u", se->rpc->rpc_sid);
	se->rpc->state = RPC_ERROR; // goto rpc_error;
      }

      if (yp == YP_WAIT)
	return YP_WAIT;
      else if (yp == YP_ERR)
	se->rpc->state = RPC_ERROR; // goto rpc_error;

      if (cbor_parse_block_end(se->cbor))
      {
	running = 0;
	se->rpc->state = RPC_DONE2;
      }
      else
	se->rpc->state = RPC_MAP_OPENED;
      break;

      /* fall through */
    case RPC_DONE2:
      mb_free(se->rpc);
      se->rpc = NULL;
      return YP_OK;

    case RPC_ERROR:
      mb_free(se->rpc);
      se->rpc = NULL;
      return YP_ERR;
    }
  }

  // Should not happen
  return YP_ERR;
}

